CREATE TABLE outbox(seq BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE, topic VARCHAR(90) NOT NULL,aggregate_id VARCHAR(80) NOT NULL,payload JSON NOT NULL);
CREATE TABLE inbox(event_id CHAR(36) PRIMARY KEY);
CREATE TABLE documents(id VARCHAR(100) PRIMARY KEY,title VARCHAR(180) NOT NULL,source VARCHAR(240) NOT NULL,body TEXT NOT NULL,version INT NOT NULL DEFAULT 1);
CREATE TABLE chunks(doc_id VARCHAR(100) NOT NULL,ordinal INT NOT NULL,body TEXT NOT NULL,embedding JSON NOT NULL,PRIMARY KEY(doc_id,ordinal),FOREIGN KEY(doc_id) REFERENCES documents(id) ON DELETE CASCADE);